CREATE TABLE public.assistant_management_grants (user_id uuid NOT NULL, client_id text NOT NULL, approved_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,client_id)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.assistant_management_grants TO authenticated; GRANT ALL ON public.assistant_management_grants TO service_role; ALTER TABLE public.assistant_management_grants ENABLE ROW LEVEL SECURITY; CREATE POLICY "Admins manage own assistant consent" ON public.assistant_management_grants FOR ALL TO authenticated USING (user_id=auth.uid() AND public.has_role(auth.uid(),'admin')) WITH CHECK (user_id=auth.uid() AND public.has_role(auth.uid(),'admin'));